    $resolved=realpath($temp);if(!$resolved||dirname($resolved)!==realpath(sys_get_temp_dir())||!preg_match('/^mco-gov-[a-f0-9]{16}$/D',basename($resolved)))throw new RuntimeException('Unsafe temp cleanup.');foreach(glob($temp.'/*')?:[] as $f)unlink($f);rmdir($temp);
